        queue.append({"product":p,"remaining":v,"day":day})
    cap_left=cap_mod if day>=189 else cap_orig
    # sort
    queue.sort(key=lambda x:(x["day"], x["remaining"], x["product"]))
    idx=0
    while cap_left>0 and idx< len(queue):
        o=queue[idx]
        p=o["product"]
        rem=o["remaining"]
        use=min(rem, cap_left//w[p])
        if use>0:
            cap_left-=use*w[p]
            o["remaining"]-=use
            stock[p]-=use
        if o["remaining"]==0:
            queue.pop(idx)
        else:
            idx+=1
    # backordered
    back={p:0 for p in stock}
    for o in queue:
        back[o["product"]]+=o["remaining"]
    print('Day',day,'stock',stock["ATN02K12P"],'back',back["ATN02K12P"], 'queue', [(o["product"],o["remaining"],o["day"]) for o in queue])

